package com.example.helpdesk.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="assets") public class Asset { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="asset_tag",unique=true,nullable=false) private String assetTag; @Column(nullable=false) private String name; private String category,manufacturer,serialNumber,notes; @ManyToOne @JoinColumn(name="assigned_user_id") private User assignedUser; @Enumerated(EnumType.STRING) private AssetStatus status; private LocalDate purchaseDate; @Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now(),updatedAt=LocalDateTime.now(); public Asset(){} public Long getId(){return id;} public String getAssetTag(){return assetTag;} public void setAssetTag(String v){assetTag=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getManufacturer(){return manufacturer;} public void setManufacturer(String v){manufacturer=v;} public String getSerialNumber(){return serialNumber;} public void setSerialNumber(String v){serialNumber=v;} public AssetStatus getStatus(){return status;} public void setStatus(AssetStatus v){status=v;} public User getAssignedUser(){return assignedUser;} public void setAssignedUser(User v){assignedUser=v;} public LocalDate getPurchaseDate(){return purchaseDate;} public void setPurchaseDate(LocalDate v){purchaseDate=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} }
